class Solution(object):
    def completePrime(self, num):
        """
        :type num: int
        :rtype: bool
        """
        def is_prime(n):
            if (n <= 1) or (n != 2 and n%2 == 0):
                return False
            for i in xrange(3, n+1, 2):
                if i*i > n:
                    break
                if n%i == 0:
                    return False
            return True

        suffix, base = 0, 1
        while num:
