# Space: O(1)
# sort
class Solution2(object):
    def countElements(self, nums, k):
        """
        :type nums: List[int]
        :type k: int
        :rtype: int
        """
        if not k:
            return len(nums)
        nums.sort()
        return next((i for i in reversed(xrange(len(nums)-k)) if nums[i] < nums[-k]), -1)+1

